  try {
    const r = await fetch(u);
    const t = await r.text();
    out.push({u, status: r.status, n: t.length, head: t.slice(0, 200)});
  } catch (e) {
    out.push({u, err: String(e)});
  }
}
return out;

const [status, tasks] = await Promise.all([
